import cmath
from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=list)
def compute_transform_pair(x, k_start, N):
    pair_result = []
    for k in range(k_start, min(k_start + 2, N)):
        X_k = 0.0j
        for n in range(N):
            angle = -2j * cmath.pi * k * n / N
            X_k += x[n] * cmath.exp(angle)
        pair_result.append(X_k)
    return pair_result

@task(returns=list)
def conjugate_pair(pair_data):
    return [val.conjugate() for val in pair_data]

def main(x):
    N = len(x)
    transform_futures = []

    for k_start in range(0, N, 2):
        res = compute_transform_pair(x, k_start, N)
        transform_futures.append(res)

    final_futures = [conjugate_pair(f) for f in transform_futures]

    results = compss_wait_on(final_futures)

    x[:] = [item for sublist in results for item in sublist]

    return x
